#!/bin/bash
set -euo pipefail
DEVICE_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
ANDROID_ROOT="$(cd -- "${DEVICE_DIR}/../../.." && pwd)"
VENDOR_DIR="${ANDROID_ROOT}/vendor/lvmi/S17Promini"
mkdir -p "${VENDOR_DIR}"
cat > "${VENDOR_DIR}/BoardConfigVendor.mk" <<'EOF'
# Generated by device/lvmi/S17Promini/setup-makefiles.sh.
BOARD_PREBUILT_VENDORIMAGE := vendor/lvmi/S17Promini/proprietary/vendor.img
EOF
cat > "${VENDOR_DIR}/S17Promini-vendor.mk" <<'EOF'
# Generated by device/lvmi/S17Promini/setup-makefiles.sh.
# Stock HALs, properties and policy are preserved in the cleaned prebuilt image.
PRODUCT_BUILD_VENDOR_IMAGE := false
EOF
cat > "${VENDOR_DIR}/.gitignore" <<'EOF'
/proprietary/vendor.img
/proprietary/vendor.json
EOF
